@Component
struct CounterBoard {
 @State count: number = 0
 fakeText(): string {
  return "this.count = 7; this.count"
 }
 fakeComment(): void {
  // this.count += 1
  /* observe this.count */
 }
 fakeTemplate(): string {
  return `this.count = 4; this.count`
 }
 realWrite(): void {
  this.count = 1
 }
 realRead(): number {
  return this.count
 }
 ordinaryIdentifier(): string {
  const count = 'count'
  return count
 }
 nestedUnknown(): void {
  const nested = { run() { this.count = 9 } }
 }
 interpolationUnknown(): string {
  return `${this.count}`
 }
 slashUnknown(): number {
  return this.count / 2
 }
}
@Component
struct OtherBoard {
 @State count: number = 0
 realWrite(): void {
  this.count = 3
 }
 realRead(): number {
  return this.count
 }
}
